package com.tekwatt.audit.repository;import com.tekwatt.audit.entity.AuditEvent;import java.time.Instant;import java.util.UUID;import org.springframework.data.domain.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;public interface AuditEventRepository extends JpaRepository<AuditEvent,UUID>{@Query("select e from AuditEvent e where e.tenantId=:tenantId and (:action is null or e.action=:action) and (:resourceType is null or e.resourceType=:resourceType) and e.occurredAt between :from and :to order by e.occurredAt desc")Page<AuditEvent>search(@Param("tenantId")UUID tenantId,@Param("action")String action,@Param("resourceType")String resourceType,@Param("from")Instant from,@Param("to")Instant to,Pageable pageable);}
